class WorkerPool(T, R)
  def initialize(
    @jobs : Channel(T),
    @worker_count : Int32,
    &@transform : T -> R
  )
    @output = Channel(R).new(capacity: @worker_count * 8)
    @finished = Channel(Nil).new
  end

  def start : self
    @worker_count.times do
      spawn do
        while (job = @jobs.receive?)
          @output.send(@transform.call(job))
        end
        @finished.send(nil)
      end
    end

    spawn do
      @worker_count.times { @finished.receive }
      @output.close
    end

    self
  end

  def results : Channel(R)
    @output
  end
end

