class LRUCache
  def initialize(@capacity : Int32)
    @store = {} of String => String
    @order = [] of String
  end

  def get(key : String) : String?
    return nil unless @store.has_key?(key)
    touch(key)
    @store[key]
  end

  def put(key : String, value : String) : Nil
    if @store.has_key?(key)
      touch(key)
      @store[key] = value
    else
      evict if @order.size >= @capacity
      @order << key
      @store[key] = value
    end
  end

  def size : Int32
    @store.size
  end

  private def touch(key : String) : Nil
    @order.delete(key)
    @order << key
  end

  private def evict : Nil
    oldest = @order.shift
    @store.delete(oldest)
  end
end

