class BoundedQueue(T)
  def initialize(@max_size : Int32)
    @data = Deque(T).new
  end

  def enqueue(item : T) : Nil
    raise "queue is full" if full?
    @data.push(item)
  end

  def dequeue : T
    raise "queue is empty" if empty?
    @data.shift
  end

  def peek : T
    raise "queue is empty" if empty?
    @data.first
  end

  def full? : Bool
    @data.size >= @max_size
  end

  def empty? : Bool
    @data.empty?
  end

  def size : Int32
    @data.size
  end
end

