struct Stopwatch
  @started_at : Time::Instant?
  @accumulated : Time::Span
  @running : Bool

  def initialize
    @started_at = nil
    @accumulated = Time::Span.zero
    @running = false
  end

  def start : self
    return self if @running
    @started_at = Time.instant
    @running = true
    self
  end

  def stop : self
    return self unless @running
    if (t = @started_at)
      @accumulated += Time.instant - t
    end
    @started_at = nil
    @running = false
    self
  end

  def reset : self
    @started_at = @running ? Time.instant : nil
    @accumulated = Time::Span.zero
    self
  end

  def elapsed : Time::Span
    if @running && (t = @started_at)
      @accumulated + (Time.instant - t)
    else
      @accumulated
    end
  end

  def running? : Bool
    @running
  end
end
